// Returns a debounced version of fn that delays invoking it until
// `ms` milliseconds have elapsed since the last time it was called.
function debounce(fn, ms) {
  // Holds the pending timer id so it can be cleared on each new call.
  let timer;
  return function (...args) {
    // Cancel any previously scheduled invocation.
    clearTimeout(timer);
    // Schedule fn to run after the quiet period, preserving `this` and arguments.
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, ms);
  };
}

